import json
from lib import *
R = J('r102'); T = R['t']; md = R['mid']
KV = lambda items, hl=(): {'items': items, 'hl': list(hl)}
def tm(lines, cur=(), mark=()): return {'lines': lines, 'cur': list(cur), 'mark': list(mark)}
def bars(items, mx, cur=(), mark=(), done=()): return {'items': items, 'max': mx, 'cur': list(cur), 'mark': list(mark), 'done': list(done)}
t0, t1, t2 = T['0'], T['0.5'], T['2']
steps = [
    step("同步请求是「发一条、等回复、再发下一条」,每条命令都要一个完整的网络往返(RTT)。管道(pipeline)是「连续发 N 条、再一次读 N 条回复」,N 条命令共用一个往返。为了在本机模拟网络,我写了一个给每个方向加固定延迟的 TCP 代理。", t=tm(['同步:发 1 → 等 1 → 发 1 → 等 1 …', '管道:发 N → 一次读 N'], cur=[0, 1]), kv=KV([['模拟', 'RTT = 0 / 1 / 4 ms(单向 0 / 0.5 / 2 ms)']], ['模拟'])),
    step(f"RTT ≈ 0(本机回环):同步 {t0[0]/1000:.0f}k 条/秒,管道 10 → {t0[1]/1000:.0f}k、100 → {t0[2]/1000:.0f}k、1000 → {t0[3]/1000:.0f}k。连没有网络延迟时,管道也快 {t0[3]/t0[0]:.0f} 倍(省的是每次的系统调用与调度)。", b=bars([['同步', t0[0] / 1000, f'{t0[0]/1000:.0f}k/s'], ['管道 10', t0[1] / 1000, f'{t0[1]/1000:.0f}k/s'], ['管道 100', t0[2] / 1000, f'{t0[2]/1000:.0f}k/s'], ['管道 1000', t0[3] / 1000, f'{t0[3]/1000:.0f}k/s']], t0[3] / 1000, done=[3]), kv=KV([['RTT ≈ 0', f'管道 1000 是同步的 {t0[3]/t0[0]:.0f} 倍']], ['RTT ≈ 0'])),
    step(f"RTT = 1 ms:同步只有 {t1[0]:.0f} 条/秒(受 RTT 上限约束),管道 1000 → {t1[3]/1000:.0f}k 条/秒,是同步的 {t1[3]/t1[0]:.0f} 倍。RTT = 4 ms:同步 {t2[0]:.0f} 条/秒,管道 1000 → {t2[3]/1000:.0f}k,{t2[3]/t2[0]:.0f} 倍。网络越慢,管道收益越大。", b=bars([['RTT 1 ms 同步', t1[0], f'{t1[0]:.0f}/s'], ['RTT 1 ms 管道 1000', t1[3], f'{t1[3]:.0f}/s'], ['RTT 4 ms 同步', t2[0], f'{t2[0]:.0f}/s'], ['RTT 4 ms 管道 1000', t2[3], f'{t2[3]:.0f}/s']], t1[3], mark=[0, 2], done=[1, 3]), kv=KV([['RTT 1 / 4 ms', f'{t1[3]/t1[0]:.0f}× / {t2[3]/t2[0]:.0f}×']], ['RTT 1 / 4 ms'])),
    step(f"管道不是事务:客户端 A 发 2000 条 INCR 的管道,客户端 B 同时反复 GET 这个计数器。B 读了 {md['n']} 次,其中 {md['mid']} 次读到的值不是 2000 的整数倍——A 的管道被执行到一半,B 看到了中间值。", t=tm(['A: pipeline × 2000 INCR', 'B: GET cnt → 读到 1780、2890、4890……'], mark=[1]), kv=KV([['B 读到中间值', f"{md['mid']} / {md['n']}"]], ['B 读到中间值'])),
    step("管道里某条命令出错,其它命令照常执行,回复按发送顺序返回:SET a 1 → OK;LPUSH a x → WRONGTYPE 错误;INCR a → 2;GET a → \"2\"。错误只出现在它自己那个位置。要原子执行需要 MULTI/EXEC(或 Lua)。", t=tm(['SET a 1     → OK', 'LPUSH a x   → WRONGTYPE …', 'INCR a       → 2', 'GET a        → "2"'], mark=[1]), kv=KV([['错误', '不中断后续命令']], ['错误'])),
]
A = dict(
    n=102, series='redis', tags='Redis,Pipeline,网络,真实验证,动画演示',
    desc=f'用可加延迟的 TCP 代理模拟网络:RTT ≈ 0 时同步 {t0[0]/1000:.0f}k、管道 1000 条 {t0[3]/1000:.0f}k 条/秒;RTT 1 ms 时同步只有 {t1[0]:.0f}、管道 {t1[3]/1000:.0f}k({t1[3]/t1[0]:.0f} 倍);RTT 4 ms 时 {t2[0]:.0f} vs {t2[3]/1000:.0f}k({t2[3]/t2[0]:.0f} 倍);管道不是事务(另一个客户端能读到中间值),某条命令出错不影响其余。',
    lead='Pipeline 是 Redis 最便宜的加速手段,但它为什么有效、有多有效、又有什么不保证?这篇用一个可以加网络延迟的 TCP 代理,把同步与不同批量的管道放在不同 RTT 下比较,再验证它「不是事务」这件最容易被忽略的事。',
    facts=[(f'{t1[3]/t1[0]:.0f} 倍', f'RTT 1 ms 时管道(1000 条/批)相对同步的吞吐:{t1[3]/1000:.0f}k vs {t1[0]:.0f} 条/秒'), (f'{t2[3]/t2[0]:.0f} 倍', f'RTT 4 ms 时的同一比值({t2[3]/1000:.0f}k vs {t2[0]:.0f})'), ('不是事务', f'另一个客户端 {md["mid"]} 次读到了管道执行一半时的中间值')],
    body=[
        sec('RTT 与吞吐', '每格 3 次取中位;RTT 0 的每格 20000 条,有延迟的每格 5000 条(RTT>0 的同步只写 2000 条)', term('', blk('r102', 1)), f'<p>同步请求的吞吐几乎被 RTT 卡死:RTT 1 ms 时只有 {t1[0]:.0f} 条/秒(约每条 1.8 ms),RTT 4 ms 时 {t2[0]:.0f} 条/秒。管道把一批命令放在一个往返里,批量越大越接近服务器自身的处理速度。批量 1000 时 RTT 从 0 增加到 4 ms,吞吐只从 {t0[3]/1000:.0f}k 降到 {t2[3]/1000:.0f}k。RTT 的模拟是我写的代理(每个方向固定延迟),不是真实网络:没有丢包、抖动。</p>'),
        sec('管道不是事务', '', term('', blk('r102', 2)), f'<p>管道只是「把多条命令一起发出去」,服务器仍然一条一条执行,并且在管道的命令之间可以插入其它客户端的命令。B 读到 {md["mid"]} 次「执行到一半」的值。需要原子性时用 <code>MULTI</code>/<code>EXEC</code> 或 Lua(第 29–38 篇)。</p>'),
        sec('出错时', '', term('', blk('r102', 3)), '<p>回复严格按发送顺序返回;某条命令出错,只是它的回复是一个错误,后面的命令照常执行。客户端要逐条检查回复。</p>'),
        sec('分步演示:为什么管道快', '', demo('Redis Pipeline 原理', [('t', 'term', '过程'), ('b', 'bars', '吞吐'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_R + '。延迟由自写的 DelayProxy 加在两个方向(TCP_NODELAY);单客户端;SET 命令', '没有验证:真实网络的抖动与丢包、多客户端并发时的叠加、管道过大对服务器内存与其它客户端延迟的影响(第 103 篇)'],
)
